version 21.4R1.12;
system {
    host-name BR-JUNIPER-SRX;
    root-authentication {
        encrypted-password "$6$rounds=656000$saltsalt$xyz123...";
    }
    login {
        message "RESTRICTED ACCESS - AUTHORIZED PERSONNEL ONLY";
        idle-timeout 10;
        user admin {
            class super-user;
            authentication {
                encrypted-password "$6$rounds=656000$saltsalt$abc789...";
            }
        }
    }
    services {
        ssh {
            protocol-version v2;
            connection-limit 5;
        }
        telnet;
        web-management {
            http {
                port 80;
            }
            https {
                port 443;
                system-generated-certificate;
            }
        }
    }
    syslog {
        archive size 100k files 3;
        user * {
            any emergency;
        }
        file messages {
            any notice;
            authorization info;
        }
    }
    ntp {
        server 172.16.1.1;
    }
}
snmp {
    community public {
        authorization read-only;
    }
}
